package com.photoprism.uploader.lab

import android.view.View
import android.view.ViewGroup
import android.widget.VideoView
import androidx.compose.ui.test.*
import androidx.compose.ui.test.junit4.createAndroidComposeRule
import androidx.test.platform.app.InstrumentationRegistry
import com.photoprism.uploader.MainActivity
import org.junit.Assume.assumeTrue
import org.junit.Rule
import org.junit.Test
import java.io.File

/** Opt-in fixture generated by ffmpeg, placed only in the isolated app's private files. */
class BackupVideoTest {
    @get:Rule val compose = createAndroidComposeRule<MainActivity>()
    @Test fun syntheticVideoOpensPlayer() {
        assumeTrue(InstrumentationRegistry.getArguments().getString("syntheticVideo") == "true")
        val context = InstrumentationRegistry.getInstrumentation().targetContext
        check(context.packageName.endsWith(".cameralab"))
        check(File(context.filesDir, "synthetic-library/whatsapp-videos/playback.mp4").isFile)
        compose.onNodeWithText("Backup").performClick()
        compose.onNodeWithText("WhatsApp videos").performClick()
        compose.waitUntil(15000) { compose.onAllNodesWithContentDescription("Play playback.mp4").fetchSemanticsNodes().isNotEmpty() }
        compose.onNodeWithContentDescription("Play playback.mp4").performClick()
        fun player(view: View): VideoView? {
            if (view is VideoView) return view
            if (view is ViewGroup) for (i in 0 until view.childCount) player(view.getChildAt(i))?.let { return it }
            return null
        }
        compose.waitUntil(15000) {
            var playing = false
            compose.runOnUiThread { playing = player(compose.activity.window.decorView)?.isPlaying == true }
            playing
        }
        compose.onNodeWithText("Unable to play this video on this device").assertDoesNotExist()
        compose.onNodeWithText("Back").performClick()
        compose.onNodeWithText("Check now").assertIsDisplayed()
    }
}
